function check(input, actual, expected) {
  const [values, insertVal] = input;
  if (!Array.isArray(actual) || actual.length !== values.length + 1) return false;
  // Removing the inserted value at its first difference from the original must give the original back.
  let i = 0;
  while (i < values.length && actual[i] === values[i]) i++;
  if (values.length > 0 && i === 0) return false;
  if (actual[i] !== insertVal) return false;
  for (let j = i; j < values.length; j++) {
    if (actual[j + 1] !== values[j]) return false;
  }
  // A circle is sorted when it drops from a bigger to a smaller value at most once.
  let drops = 0;
  for (let j = 0; j < actual.length; j++) {
    if (actual[j] > actual[(j + 1) % actual.length]) drops++;
  }
  return drops <= 1;
}

