function validate([head, insertVal]) {
  if (!Array.isArray(head) || head.length > 50000) return 'head lists at most 5 * 10^4 values.';
  if (head.some(v => !Number.isInteger(v) || v < -1000000 || v > 1000000)) return 'Node values are whole numbers from -10^6 to 10^6.';
  if (!Number.isInteger(insertVal) || insertVal < -1000000 || insertVal > 1000000) return 'insertVal is a whole number from -10^6 to 10^6.';
  let drops = 0;
  for (let i = 0; i < head.length; i++) {
    if (head[i] > head[(i + 1) % head.length]) drops++;
  }
  if (drops > 1) return 'Going around the circle, the values must be sorted from some starting node.';
  return null;
}

