function adapt(input, solve, kit) {
  const [values, insertVal] = input;
  const nodes = kit.listNodes(values);
  if (nodes.length > 0) nodes[nodes.length - 1].next = nodes[0];
  const head = nodes.length > 0 ? nodes[0] : null;
  const result = solve(head, insertVal);
  if (result === undefined) throw new Error('The solution did not return a value.');
  if (head !== null && result !== head) throw new Error('Return the node you were given.');
  if (result === null || typeof result !== 'object') throw new Error('For an empty list, return the new node.');
  if (!nodes.every((node, i) => node.val === values[i])) throw new Error('Do not change the values of existing nodes.');
  // Walk once around the circle: the original nodes must appear in order, plus exactly one new node.
  const original = new Set(nodes);
  const out = [];
  let seen = 0;
  let added = 0;
  let node = result;
  do {
    if (node === null || typeof node !== 'object') throw new Error('The list must stay circular.');
    if (out.length > nodes.length) throw new Error('The circle must hold the original nodes plus one new node.');
    if (original.has(node)) {
      if (node !== nodes[seen]) throw new Error('Keep the existing nodes in their original order.');
      seen++;
    } else {
      added++;
      if (node.val !== insertVal) throw new Error('The new node must hold insertVal.');
    }
    out.push(node.val);
    node = node.next;
  } while (node !== result);
  if (seen !== nodes.length || added !== 1) throw new Error('The circle must hold the original nodes plus one new node.');
  return out;
}

