  const node = new ListNode(insertVal);
  if (head === null) {
    node.next = node;
    return node;
  }

  let prev = head;
  let curr = head.next;
  do {
    if (prev.val <= insertVal && insertVal <= curr.val) {
      break;
    }
    if (prev.val > curr.val && (insertVal >= prev.val || insertVal <= curr.val)) {
      break;
    }
    prev = curr;
    curr = curr.next;
  } while (prev !== head);

  prev.next = node;
  node.next = curr;
  return head;
}

