function insert(head, insertVal) {
  const fresh = new ListNode(insertVal);
  if (!head) {
    fresh.next = fresh;
    return fresh;
  }
  const ring = [head];
  for (let p = head.next; p !== head; p = p.next) ring.push(p);
  const sortedCircle = (vals) => vals.filter((v, i) => v > vals[(i + 1) % vals.length]).length <= 1;
  // Try every gap in turn and keep the first one that leaves the circle sorted.
  for (let j = 0; j < ring.length; j++) {
    const vals = ring.map(p => p.val);
    vals.splice(j + 1, 0, insertVal);
    if (sortedCircle(vals)) {
      fresh.next = ring[j].next;
      ring[j].next = fresh;
      return head;
    }
  }
  return head;
}

