function generate(rand, size) {
  const large = size === 'large';
  const span = large ? 1000000 : 5;
  const pick = () => Math.floor(rand() * (2 * span + 1)) - span;
  const n = large ? 1500 + Math.floor(rand() * 501) : rand() < 0.1 ? 0 : 1 + Math.floor(rand() * 6);
  const same = rand() < 0.15 ? pick() : null;
  const sorted = Array.from({ length: n }, () => same === null ? pick() : same).sort((x, y) => x - y);
  const shift = n > 0 ? Math.floor(rand() * n) : 0;
  const head = sorted.slice(shift).concat(sorted.slice(0, shift));
  const insertVal = n > 0 && rand() < 0.3 ? sorted[Math.floor(rand() * n)] : pick();
  return [head, insertVal];
}
